local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
hl.bind("CTRL + ALT + T", hl.dsp.exec_cmd("kitty"))
hl.bind("SUPER + Q", hl.dsp.exec_cmd("kitty"))
hl.bind("SUPER + F", hl.dsp.window.fullscreen())

function toggle_workspace_floating()
    local workspace = hl.get_active_workspace()
    if workspace == nil or workspace.special then return end

    local windows = {}
    for _, window in ipairs(hl.get_workspace_windows(workspace.id)) do
        if window.workspace == workspace and not window.workspace.special then
            table.insert(windows, window)
        end
    end

    if #windows == 0 then return end

    local should_float = false
    for _, window in ipairs(windows) do
        if not window.floating then
            should_float = true
            break
        end
    end

    local original_sizes = {}

    if should_float then
        for _, window in ipairs(windows) do
            local size = window.size
            if type(size) == "table" then
                local width = size.x or size[1]
                local height = size.y or size[2]

                if type(width) == "number" and type(height) == "number" then
                    table.insert(original_sizes, {
                        window = window,
                        width = width,
                        height = height
                    })
                end
            end
        end
    end

    for _, window in ipairs(windows) do
        hl.dispatch(hl.dsp.window.float({
            window = window,
            action = should_float and "enable" or "disable"
        }))
    end

    if should_float then
        for _, entry in ipairs(original_sizes) do
            hl.dispatch(hl.dsp.window.resize({
                window = entry.window,
                x = entry.width,
                y = entry.height,
                relative = false
            }))
        end
    end
end

hl.bind("SUPER + T", toggle_workspace_floating)
hl.bind("ALT + F4", hl.dsp.exec_cmd("hyprctl kill"))
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd([[sh -c 'geometry=$(slurp) || exit; [ -n "$geometry" ] || exit; grim -g "$geometry" - | wl-copy']]))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("~/.local/bin/toggle-appmenu.sh"))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + X", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Move windows with middle mouse button + drag
hl.bind("mouse:274", function()
    local win = hl.get_active_window()
    if win ~= nil and win.fullscreen ~= 2 then
        hl.dispatch(hl.dsp.window.drag())
    end
end, { mouse = true })
hl.bind("SUPER + mouse:274", hl.dsp.window.close(), { mouse = true })
hl.bind("mouse:272", hl.dsp.exec_cmd("~/.local/bin/rofi-click-to-close.sh"), {
    mouse = true,
    non_consuming = true
})

-- Laptop multimedia keys for volume and LCD brightness
